import React, { useState } from 'react';
import chatBgImg from '../../assets/nen_khung_chat.jpg'; 

const QuanLyCuDan = () => {
    // State lưu phòng duy nhất được chọn
    const [selectedRoom, setSelectedRoom] = useState(null);

    // Giả lập dữ liệu cư dân (Sau này bạn sẽ fetch từ Backend)
    const residentData = {
        "101": { name: "Nguyễn Văn A", gender: "Nam", phone: "0901.234.xxx", members: 3, parking: "Lô A-05" },
        "102": { name: "Trần Thị B", gender: "Nữ", phone: "0912.888.xxx", members: 2, parking: "Không có" },
        // ... các phòng khác
    };

    // Tạo danh sách 45 phòng
    const allRooms = [];
    for (let floor = 1; floor <= 9; floor++) {
        for (let num = 1; num <= 5; num++) {
            allRooms.push(`${floor}0${num}`);
        }
    }

    return (
        <div style={{
            flex: 1, borderRadius: '30px', display: 'flex', flexDirection: 'column', 
            backgroundImage: `url(${chatBgImg})`, backgroundSize: 'cover',
            backgroundPosition: 'center', overflow: 'hidden'
        }} className="glass-card">

            <div style={{ padding: '20px', color: '#fff' }}>
                <h2 style={{ margin: 0, textShadow: '1px 1px 4px rgba(0,0,0,0.5)' }}>Quản lý cư dân</h2>
            </div>

            <div style={{ flex: 1, padding: '0 20px 20px 20px', display: 'flex', gap: '25px', overflow: 'hidden' }}>

                {/* BÊN TRÁI: BẢNG CHỌN PHÒNG (Mini) */}
                <div style={{ 
                    width: '200px', 
                    display: 'grid', 
                    gridTemplateColumns: 'repeat(5, 1fr)', 
                    gap: '5px', 
                    alignContent: 'flex-start', 
                    overflowY: 'auto',
                    padding: '10px',
                    backgroundColor: 'rgba(255,255,255,0.1)',
                    borderRadius: '15px'
                }}>
                    {allRooms.map(room => (
                        <div 
                            key={room} 
                            onClick={() => setSelectedRoom(room)}
                            style={{ 
                                background: selectedRoom === room ? '#8b5e5e' : 'white', 
                                color: selectedRoom === room ? 'white' : '#333',
                                padding: '6px 0', 
                                borderRadius: '6px', 
                                textAlign: 'center', 
                                fontSize: '10px', 
                                fontWeight: 'bold', 
                                cursor: 'pointer',
                                transition: '0.2s',
                                border: 'none'
                            }}
                        >
                            {room}
                        </div>
                    ))}
                </div>

                {/* BÊN PHẢI: KHUNG CHI TIẾT CƯ DÂN (Khung mờ) */}
                <div style={{ 
                    flex: 1, 
                    backgroundColor: 'rgba(255,255,255,0.15)', 
                    backdropFilter: 'blur(10px)', 
                    borderRadius: '20px', 
                    border: '1px solid rgba(255,255,255,0.2)',
                    display: 'flex',
                    flexDirection: 'column',
                    justifyContent: 'center',
                    alignItems: 'center',
                    padding: '40px',
                    color: '#fff'
                }}>
                    {selectedRoom ? (
                        <div style={{ width: '100%', textAlign: 'left' }}>
                            {/* Số phòng hiển thị lớn */}
                            <div style={{ fontSize: '48px', fontWeight: 'bold', marginBottom: '20px', borderBottom: '2px solid #fff', display: 'inline-block' }}>
                                PHÒNG: {selectedRoom}
                            </div>

                            <div style={{ fontSize: '18px', lineHeight: '2', textShadow: '1px 1px 2px #000' }}>
                                <p><strong>Tên chủ phòng:</strong> {residentData[selectedRoom]?.name || "Chưa có dữ liệu"}</p>
                                <p><strong>Giới tính:</strong> {residentData[selectedRoom]?.gender || "---"}</p>
                                <p><strong>Liên hệ:</strong> {residentData[selectedRoom]?.phone || "---"}</p>
                                <p><strong>Số lượng thành viên gia đình:</strong> {residentData[selectedRoom]?.members || 0}</p>
                                <p><strong>Bãi đỗ xe:</strong> {residentData[selectedRoom]?.parking || "Không có"}</p>
                            </div>

                            <button style={{
                                marginTop: '30px', padding: '10px 25px', borderRadius: '10px', border: 'none',
                                backgroundColor: '#333', color: '#fff', fontWeight: 'bold', cursor: 'pointer'
                            }}>
                                Chỉnh sửa thông tin
                            </button>
                        </div>
                    ) : (
                        <p style={{ fontSize: '18px', opacity: 0.8 }}>Vui lòng chọn một phòng để xem chi tiết cư dân</p>
                    )}
                </div>
            </div>
        </div>
    );
};

export default QuanLyCuDan;
